insert into auth.sessions(id,user_id,factor_id,aal,created_at,updated_at) values('ff300000-0000-4000-8000-000000000001','ff000000-0000-4000-8000-000000000001','ff200000-0000-4000-8000-000000000001','aal2',now(),now()),('ff300000-0000-4000-8000-000000000002','ff000000-0000-4000-8000-000000000002','ff200000-0000-4000-8000-000000000002','aal2',now(),now());
insert into auth.mfa_amr_claims(id,session_id,authentication_method,created_at,updated_at) values('ff400000-0000-4000-8000-000000000001','ff300000-0000-4000-8000-000000000001','totp',now(),now()),('ff400000-0000-4000-8000-000000000002','ff300000-0000-4000-8000-000000000002','totp',now(),now());

set local role authenticated;
set local request.jwt.claims='{"sub":"ff000000-0000-4000-8000-000000000001","session_id":"ff300000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}';
select set_config('test.pack_request',public.propose_student_recovery('ff100000-0000-4000-8000-000000000003','forgotten_password',true,true)::text,true);
set local request.jwt.claims='{"sub":"ff000000-0000-4000-8000-000000000002","session_id":"ff300000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}';
select public.decide_student_recovery(current_setting('test.pack_request')::uuid,true,true,true);
select throws_ok($$select public.issue_student_recovery_pack(current_setting('test.pack_request')::uuid,'ff000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64))$$,'42501',null,'browser cannot issue trusted recovery proof');
select throws_ok($$select public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))$$,'42501',null,'browser cannot bypass trusted password mutation');
reset role;
update public.role_assignments set revoked_at=now() where person_id='ff100000-0000-4000-8000-000000000001';
select throws_ok($$select public.issue_student_recovery_pack(current_setting('test.pack_request')::uuid,'ff000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64))$$,'42501',null,'revoked proposer cannot authorize issuance');
update public.role_assignments set revoked_at=null where person_id='ff100000-0000-4000-8000-000000000001';
update auth.mfa_amr_claims set updated_at=now()-interval '20 minutes' where session_id='ff300000-0000-4000-8000-000000000002';
select throws_ok($$select public.issue_student_recovery_pack(current_setting('test.pack_request')::uuid,'ff000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64))$$,'42501',null,'stale approver cannot issue pack');
update auth.mfa_amr_claims set updated_at=now() where session_id='ff300000-0000-4000-8000-000000000002';
select throws_ok($$select public.issue_student_recovery_pack(current_setting('test.pack_request')::uuid,'ff000000-0000-4000-8000-000000000003',repeat('a',64),repeat('b',64))$$,'42501',null,'target cannot issue own pack');
select lives_ok($$select public.issue_student_recovery_pack(current_setting('test.pack_request')::uuid,'ff000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64))$$,'approved fresh independent administrator issues pack');
select throws_ok($$select public.issue_student_recovery_pack(current_setting('test.pack_request')::uuid,'ff000000-0000-4000-8000-000000000002',repeat('a',64),repeat('b',64))$$,'55000',null,'issuance replay denied');
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('e',64),'link',repeat('c',64),repeat('d',64))),0,'wrong proof denied');
select is((select attempt_count from public.account_action_tokens where person_id='ff100000-0000-4000-8000-000000000003'),1,'wrong proof attempt durably recorded');
update public.memberships set status='suspended' where person_id='ff100000-0000-4000-8000-000000000001';
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))),0,'suspended proposer blocks consumption');
update public.memberships set status='active' where person_id='ff100000-0000-4000-8000-000000000001';
update public.role_assignments set revoked_at=now() where person_id='ff100000-0000-4000-8000-000000000002';
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))),0,'revoked approver blocks consumption');
update public.role_assignments set revoked_at=null where person_id='ff100000-0000-4000-8000-000000000002';
update auth.mfa_amr_claims set updated_at=now()-interval '20 minutes' where session_id='ff300000-0000-4000-8000-000000000001';
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))),0,'stale proposer verification blocks consumption');
update auth.mfa_amr_claims set updated_at=now() where session_id='ff300000-0000-4000-8000-000000000001';
update auth.users set email='changed@fixture.invalid' where id='ff000000-0000-4000-8000-000000000003';
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))),0,'changed canonical Auth binding blocks consumption');
update auth.users set email='dxm-7k3m9q2rw5t2@members.dexam.invalid' where id='ff000000-0000-4000-8000-000000000003';
update public.account_action_tokens set created_at=now()-interval '16 minutes',expires_at=now()-interval '1 minute' where person_id='ff100000-0000-4000-8000-000000000003';
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))),0,'expired pack denied');
update public.account_action_tokens set expires_at=now()+interval '15 minutes',invalidated_at=now() where person_id='ff100000-0000-4000-8000-000000000003';
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))),0,'cancelled proof denied');
update public.account_action_tokens set invalidated_at=null,attempt_count=7 where person_id='ff100000-0000-4000-8000-000000000003';
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('e',64),'link',repeat('c',64),repeat('d',64))),0,'eighth wrong proof denied');
select is((select attempt_count from public.account_action_tokens where person_id='ff100000-0000-4000-8000-000000000003'),8,'eight attempts exhaust token');
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))),0,'correct proof cannot bypass exhausted attempts');
update public.account_action_tokens set attempt_count=1 where person_id='ff100000-0000-4000-8000-000000000003';
update public.student_recovery_throttles set attempts=20 where identifier_hash=repeat('c',64);
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))),0,'member hourly budget enforced');
update public.student_recovery_throttles set attempts=1 where identifier_hash=repeat('c',64);
update public.student_recovery_throttles set attempts=100 where identifier_hash=repeat('d',64);
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))),0,'shared hourly budget enforced');
update public.student_recovery_throttles set attempts=1;
insert into auth.sessions(id,user_id,created_at,updated_at) values('ff300000-0000-4000-8000-000000000003','ff000000-0000-4000-8000-000000000003',now()-interval '1 minute',now());
set local role authenticated;
set local request.jwt.claims='{"sub":"ff000000-0000-4000-8000-000000000003","session_id":"ff300000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}';
select is(public.current_person_id(),'ff100000-0000-4000-8000-000000000003'::uuid,'live student identity resolves before reset');
reset role;
select set_config('test.execution',(select execution_key::text from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('b',64),'backup',repeat('c',64),repeat('d',64))),true);
select is((select status from public.student_recovery_requests where id=current_setting('test.pack_request')::uuid),'executing','valid backup proof claims exclusive execution');
select is((select count(*)::integer from public.claim_student_recovery('DXM-7K3M9Q2RW5T2',repeat('a',64),'link',repeat('c',64),repeat('d',64))),0,'alternate proof replay cannot claim second execution');
set local role authenticated;
select is(public.current_person_id(),null::uuid,'old student session immediately denied before provider mutation');
reset role;
update public.student_recovery_requests set created_at=now()-interval '16 minutes',expires_at=now()-interval '1 minute' where id=current_setting('test.pack_request')::uuid;
set local role authenticated;
set local request.jwt.claims='{"sub":"ff000000-0000-4000-8000-000000000002","session_id":"ff300000-0000-4000-8000-000000000002","role":"authenticated","aal":"aal2"}';
select throws_ok($$select public.cancel_student_recovery(current_setting('test.pack_request')::uuid)$$,'55000',null,'executing reset cannot be cancelled after proposal expiry');
select throws_ok($$select public.propose_student_recovery('ff100000-0000-4000-8000-000000000003','forgotten_password',true,true)$$,'55000',null,'executing reset cannot be superseded after proposal expiry');
reset role;
insert into auth.sessions(id,user_id,created_at,updated_at) values('ff300000-0000-4000-8000-000000000004','ff000000-0000-4000-8000-000000000003',clock_timestamp(),clock_timestamp());
set local role authenticated;
set local request.jwt.claims='{"sub":"ff000000-0000-4000-8000-000000000003","session_id":"ff300000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal1"}';
select is(public.current_person_id(),null::uuid,'new signin inside mutation window blocked while outcome uncertain');
reset role;
select throws_ok($$select public.finish_student_recovery(current_setting('test.pack_request')::uuid,gen_random_uuid(),true)$$,'42501',null,'wrong execution proof cannot finalize');
select is(public.finish_student_recovery(current_setting('test.pack_request')::uuid,current_setting('test.execution')::uuid,true),true,'known successful provider outcome finalizes exact execution');
set local role authenticated;
select is(public.current_person_id(),null::uuid,'final cutoff blocks session minted during mutation window');
set local request.jwt.claims='{"sub":"ff000000-0000-4000-8000-000000000003","session_id":"not-a-session","role":"authenticated","aal":"aal1"}';
select is(public.current_person_id(),null::uuid,'malformed student session denied without cast error');
reset role;
select throws_ok($$select public.finish_student_recovery(current_setting('test.pack_request')::uuid,current_setting('test.execution')::uuid,true)$$,'42501',null,'finalization replay denied');
select is((select member_id from public.people where id='ff100000-0000-4000-8000-000000000003'),'DXM-7K3M9Q2RW5T2','permanent Member ID preserved');
select is((select status::text from public.enrollments where person_id='ff100000-0000-4000-8000-000000000003'),'completed','ended enrolment is not restored');
select is((select count(*)::integer from public.role_assignments where person_id='ff100000-0000-4000-8000-000000000003'),0,'reset grants no staff roles');
select * from finish();
rollback;

